import numpy as np
from scipy.optimize import root_scalar

def g(X):
    # Constraint: 2X^3 + Z^3 = 1, where Z = X/(2X-1)
    if abs(2*X - 1) < 1e-12:
        return np.inf
    Z = X / (2*X - 1)
    return 2*X**3 + Z**3 - 1

def H(X):
    # H(X) = 2(X^2+X) + Z^2+Z, where Z = X/(2X-1)
    if abs(2*X - 1) < 1e-12:
        return -np.inf
    Z = X / (2*X - 1)
    return 2*(X**2 + X) + (Z**2 + Z)

# Search for roots in the interval (0, 0.5).
# g(0) = -1.
# g(0.5 + epsilon) = +inf.
# We use the bracketed search.
try:
    result = root_scalar(g, bracket=[0, 0.5], method='brentq')

    if result.converged:
        X_crit = result.root
        H_crit = H(X_crit)

        print(f"X_crit found with high precision: {X_crit}")
        print(f"Maximum value of H at this X_crit: {H_crit}")
    else:
        print("Root finding failed to converge.")

except ValueError as e:
    print(f"Root finding failed (ValueError): {e}")
